// Escala de tamaños del sistema — 5 tokens, un solo lugar donde viven.
// Cualquier ajuste futuro (ej. "los íconos de nav se ven grandes") se
// hace ACÁ una vez, no buscando cada renderIcon(..., {size: N}) suelto
// por el código.
//   xs (16) — microacciones: badges, links chicos, ítems de timeline
//   sm (18) — acciones secundarias: botones con ícono+texto
//   md (20) — botones principales / listas: CTA de nav, ítems de menú
//   lg (24) — navegación principal y bloques importantes: nav inferior,
//             topbar, títulos de vista (h1)
//   xl (32) — bloque ilustrado: ícono protagonista de un estado vacío
const ICON_SIZES = { xs: 16, sm: 18, md: 20, lg: 24, xl: 32 };

// Devuelve el <svg> de un ícono del sistema como string HTML, listo para
// interpolar en un template literal — mismo lugar exacto donde antes iba
// un emoji (ej. `<span>${renderIcon('editar', { scale: 'sm' })}</span>`).
// Si el nombre no existe en ICON_PATHS, devuelve '' en vez de romper el
// render (mismo criterio defensivo que ya usa el resto de la app — ver
// eventoIcon()). Siempre agrega la clase `icon-<scale>` cuando se pidió
// por token (no cuando se pasó un `size` numérico puntual), para que el
// tamaño también quede controlable por CSS si hiciera falta (ver
// .icon-xs/.icon-sm/.icon-md/.icon-lg/.icon-xl en styles.css).
function renderIcon(name, opts) {
  const d = ICON_PATHS[name];
  if (!d) return '';
  const o = opts || {};
  const scale = o.scale || 'md';
  const size = o.size || ICON_SIZES[scale] || ICON_SIZES.md;
  const scaleClass = o.size ? '' : ` icon-${scale}`;
  const extraClass = o.className ? ` ${o.className}` : '';
  const titleAttr = o.title ? ` role="img" aria-label="${o.title}"` : ' aria-hidden="true"';
  return `<svg class="icon${scaleClass}${extraClass}" width="${size}" height="${size}" viewBox="0 0 100 100" fill-rule="evenodd"${titleAttr}><path d="${d}"/></svg>`;
}

window.ICON_PATHS = ICON_PATHS;
window.ICON_SIZES = ICON_SIZES;
window.renderIcon = renderIcon;
